   142→func TestFilterAndNormalizePaths_SiblingDirectories(t *testing.T) {
   143→	// This test verifies the fix for the bug where files in sibling directories
   144→	// were filtered out when Claude runs from a subdirectory.
   145→	// When Claude is in /repo/frontend and edits /repo/api/file.ts,
   146→	// the relative path would be ../api/file.ts which was incorrectly filtered.
   147→	// The fix uses repo root instead of cwd, so paths should be api/file.ts.
   148→
   149→	tests := []struct {
   150→		name     string
   151→		files    []string
   152→		basePath string // simulates repo root or cwd
   153→		want     []string
   154→	}{
   155→		{
   156→			name: "files in sibling directories with repo root base",
   157→			files: []string{
   158→				"/repo/api/src/lib/github.ts",
   159→				"/repo/api/src/types.ts",
   160→				"/repo/frontend/src/pages/api.ts",
   161→			},
   162→			basePath: "/repo", // repo root
   163→			want: []string{
   164→				"api/src/lib/github.ts",
   165→				"api/src/types.ts",
   166→				"frontend/src/pages/api.ts",
   167→			},
   168→		},
   169→		{
   170→			name: "files in sibling directories with subdirectory base (old buggy behavior)",
   171→			files: []string{
   172→				"/repo/api/src/lib/github.ts",
   173→				"/repo/frontend/src/pages/api.ts",
   174→			},
   175→			basePath: "/repo/frontend", // cwd in subdirectory
   176→			want: []string{
   177→				// Only frontend file should remain, api file gets filtered
   178→				// because ../api/... starts with ..
   179→				"src/pages/api.ts",
   180→			},
   181→		},
   182→		{
   183→			name: "relative paths pass through unchanged",
   184→			files: []string{
   185→				"src/file.ts",
   186→				"lib/util.go",
   187→			},
   188→			basePath: "/repo",
   189→			want: []string{
   190→				"src/file.ts",
   191→				"lib/util.go",
   192→			},
   193→		},
   194→		{
   195→			name: "infrastructure paths are filtered",
   196→			files: []string{
   197→				"/repo/src/file.ts",
   198→				"/repo/.entire/metadata/session.json",
   199→			},
   200→			basePath: "/repo",
   201→			want: []string{
   202→				"src/file.ts",
   203→				// .entire path should be filtered
   204→			},
   205→		},
   206→	}
   207→
   208→	for _, tt := range tests {
   209→		t.Run(tt.name, func(t *testing.T) {
   210→			got := FilterAndNormalizePaths(tt.files, tt.basePath)
   211→			if len(got) != len(tt.want) {
   212→				t.Errorf("FilterAndNormalizePaths() returned %d files, want %d\ngot: %v\nwant: %v",
   213→					len(got), len(tt.want), got, tt.want)
   214→				return
   215→			}
   216→			for i, want := range tt.want {
   217→				if got[i] != want {
   218→					t.Errorf("FilterAndNormalizePaths()[%d] = %v, want %v", i, got[i], want)
   219→				}
   220→			}
   221→		})
   222→	}
   223→}
